#[test]
fn selected_nodes_cursor_matches_language_neutral_control_escapes_and_external_json() {
    let fixture: ::serde_json::Value = ::serde_json::from_str(include_str!("../../🧫️fixtures/📝️selection-json/🔣️.json")).expect("selection JSON vectors");
    for row in fixture["cases"].as_array().expect("cases") {
        let ids = row["nodes"].as_array().expect("nodes").iter().map(|value| value.as_str().expect("id").to_string()).collect::<Vec<_>>();
        let mut host = DagHost::from_host_snapshot_without_layout(DagHostSnapshot { nodes: ids.iter().map(|id| DagNodeSpec { id: id.clone(), ..Default::default() }).collect(), edges: vec![], ..Default::default() });
        host.set_selection(&ids);
        let oracle = ::serde_json::to_vec(&ids).expect("third-party JSON encoding");
        assert_eq!(oracle, row["expected"].as_str().expect("wire").as_bytes());
        let mut cursor = DagSelectedNodesJsonCursor::default();
        let mut output = Vec::new();
        let mut census = None;
        let mut complete = false;
        for _ in 0..4096 {
            match cursor.step(&host, cursor_grant()).expect("one-unit grant") {
                DagCursorStep::Census { bytes } => census = Some(bytes),
                DagCursorStep::Byte(byte) => output.push(byte),
                DagCursorStep::Complete => { complete = true; break; }
                DagCursorStep::Progress { .. } => {}
            }
        }
        assert!(complete, "bounded selection wire completes");
        assert_eq!(census, Some(oracle.len()));
        assert_eq!(output, oracle);
        assert_eq!(cursor.step(&host, cursor_grant()), Ok(DagCursorStep::Complete));
    }
}
